head.script:
// 테스트 설명, 유효성 값 설정
//  ★ Method _3 : mergeOptionStr = byrestriccol (세로 제한 병합). description 은 _1 과 동일.
scwin.tData = {
    "description" : "[gridView > M > mergeCellsFixedCols]<br/>GridView 컴포넌트의 mergeCellsFixedCols 속성을 설정합니다.",
    "validation" : [
        "mergeOptionStr 'byrestriccol' 설정 시 왼쪽 Column 이 병합된 범위 내에서 'bycol' 방식으로 병합을 수행합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// 검증 데이터 — byrestriccol(세로 제한) 전용. 고정 4열(col1~col4)의 계층형 cascade. (P_FC_3 데이터와 동일)
//  · col1 사업부  : 영업본부(0~2) / 관리본부(3~5)
//  · col2 팀      : 1팀(0~1) / 2팀(2) / 3팀(3~5)        (byrestriccol 제한 경계)
//  · col3 평가등급 : 우수(0~4) / 보통(5)
//        byrestriccol → 평가등급(우수)이 왼쪽 col2(팀) 경계로 제한 → 우수가 1팀[0~1]/2팀[2]/3팀[3~4] 로 잘게 세로병합 (왼쪽 그룹 다르면 미병합)
//  · col4 비고    : col3 과 동일값(우수/보통)
//  · col5 메모    : 행별 모두 다른 값 → 비고정(스크롤) 영역. 가로 스크롤로 고정 4열을 인지시키는 용도이며 병합 대상 아님.
scwin.MERGE_DATA = [
    { "col1": "영업본부", "col2": "1팀", "col3": "우수", "col4": "우수", "col5": "메모1" },
    { "col1": "영업본부", "col2": "1팀", "col3": "우수", "col4": "우수", "col5": "메모2" },
    { "col1": "영업본부", "col2": "2팀", "col3": "우수", "col4": "우수", "col5": "메모3" },
    { "col1": "관리본부", "col2": "3팀", "col3": "우수", "col4": "우수", "col5": "메모4" },
    { "col1": "관리본부", "col2": "3팀", "col3": "우수", "col4": "우수", "col5": "메모5" },
    { "col1": "관리본부", "col2": "3팀", "col3": "보통", "col4": "보통", "col5": "메모6" }
];



// comp 생성 : 고정 Column 영역(fixedColumn=4) 그리드 1개를 동적 생성한다. (P_FC_3 과 동일 데이터·target)
//  ★ Method 샘플이므로 mergeCellsFixedCols 는 생성 attribute 로 주지 않고, par_mergeOptionStr 선택 후 mergeCellsFixedCols 버튼으로 적용한다.
//  ★ 시연 컬럼(col1~col4)을 모두 fixedColumn 고정 영역에 두어야 mergeCellsFixedCols(고정 Column 영역 한정) 가 적용된다.
scwin.comp_init = async function () {
    // 기존 target / label / DataList 정리 (Target 재생성 시 동일 id 재생성이 무시되지 않도록 먼저 제거)
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove(dlt_bind.id);
    }
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="고정4열(col1~col4). par_mergeOptionStr 선택 후 mergeCellsFixedCols 버튼으로 적용. byrestriccol = 평가등급(우수)이 왼쪽 팀 경계로 제한되어 1팀[행0~1]/2팀[행2]/3팀[행3~4] 로 잘게 세로병합 (col5 메모는 비고정)"', '', 'label1');

    // 공통 계층형 DataList 생성 후 공통 데이터 적재
    //  ★ 공통 createDynamicDataList 는 col1~col4 만 정의하므로, 비고정 스크롤용 col5 까지 담기 위해 5개 컬럼 DataList 를 직접 생성한다.
    let dlNS = $c.gcm.getNameSpace();
    let strDL = '';
    strDL += '<w2:dataList ' + dlNS + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDL += '<w2:columnInfo>';
    strDL += '<w2:column id="col1" name="col1" dataType="text"></w2:column>';
    strDL += '<w2:column id="col2" name="col2" dataType="text"></w2:column>';
    strDL += '<w2:column id="col3" name="col3" dataType="text"></w2:column>';
    strDL += '<w2:column id="col4" name="col4" dataType="text"></w2:column>';
    strDL += '<w2:column id="col5" name="col5" dataType="text"></w2:column>';
    strDL += '</w2:columnInfo>';
    strDL += '<w2:data use="true"></w2:data>';
    strDL += '</w2:dataList>';
    $p.data.create(strDL);
    let arrDC = $p.data.getAllDataCollection("object");
    scwin["dlt_bind"] = arrDC[arrDC.length - 1];
    dlt_bind.setJSON(scwin.MERGE_DATA, false);

    // ★ 고정 Column 수 = 4 (시연 컬럼 col1~col4 전부 고정 영역에 포함)
    let properties = {
        dataList: "data:" + dlt_bind.id,
        fixedColumn: 4
    };
    let cList = $c.gcm.createCList(properties);

    // target 생성 (mergeCellsFixedCols 속성은 부여하지 않음 → 버튼 클릭 시 메소드로 적용)
    let grp_comp = document.querySelector('.tc_group_basic');
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    //  ★ 고정 4열(col1~col4=440) + 비고정 col5(200) = 640 으로 그리드 폭(520)보다 크게 하여 가로 스크롤이 생기도록 함
    //     → col1~col4(고정)는 스크롤해도 그대로 남고 col5(비고정)만 스크롤되어 고정 영역을 인지할 수 있다.
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' checkAllType="false" defaultCellHeight="38" id="" style="width:520px;height:310px;">';
    strTarget += '<w2:caption style="" id="caption1" value="mergeCellsFixedCols sample (고정 Column 영역 / 제한 병합)"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="110" style="" inputType="text" id="column1" value="사업부(고정)"></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="column2" value="팀(고정)"></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="column3" value="평가등급(고정)"></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="column4" value="비고(고정)"></w2:column>';
    strTarget += '<w2:column width="200" style="" inputType="text" id="column5" value="메모(col5,비고정)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="110" style="" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '<w2:column width="200" style="" inputType="text" id="col5" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// mergeCellsFixedCols 실행 : par_mergeOptionStr 값(필수)으로 target1.mergeCellsFixedCols(mergeOptionStr) 호출
//  · options(선택) 파라미터는 별도 샘플에서 다루므로 여기서는 생략한다.
scwin.btn_mergeCellsFixedCols_onclick = function (e) {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    let mode = par_mergeOptionStr.getValue();

    target1.mergeCellsFixedCols(mode);

    bottom.setReturnValue("[옵션] mergeCellsFixedCols=" + target1.options.mergeCellsFixedCols + " / mergeOptionStr='" + mode + "'");
    bottom.setReturnValue("[고정 Column 수] fixedColumn : " + (target1.options.fixedColumn || 0));

    scwin.printMergeState(bottom, mode);
}



// 병합 상태 확인 : 고정 영역 Body td 의 rowSpan/colSpan 을 읽어 세로/가로/블록 병합 그룹을 출력하고,
//  제한(왼쪽 Cell 그룹 불일치)으로 미병합되는 경계를 명확히 출력한다.
//  - td 셀렉터는 gid = target1.id 사용(e.target.id 는 버튼 id 라 사용 불가)
//  - 흡수되어 표시되지 않는 td 와 중복 키(고정/스크롤 영역 중복 id)는 제외
scwin.printMergeState = function (bottom, mode) {
    let gid = target1.id;
    let tds = document.querySelectorAll("td[id*='" + gid + "_cell_']");
    if (tds.length === 0) {
        bottom.setReturnValue("body cell td 를 찾을 수 없습니다.");
        return;
    }

    let descs = [];
    let seen = {};

    for (let i = 0; i < tds.length; i++) {
        let td = tds[i];
        if (getComputedStyle(td).display === 'none' || td.offsetParent === null) continue;
        let rs = td.rowSpan || 1;
        let cs = td.colSpan || 1;
        let m = td.id.match(/_cell_(\d+)_(\d+)/);
        if (!m) continue;
        let r = Number(m[1]), c = Number(m[2]);

        let key = r + "_" + c;
        if (seen[key]) continue;
        seen[key] = true;

        if (rs <= 1 && cs <= 1) continue;
        let val = (td.textContent || "").trim();
        if (rs > 1 && cs === 1) {
            descs.push("세로병합 col" + (c + 1) + " [행" + r + "~행" + (r + rs - 1) + "] = '" + val + "'");
        } else if (cs > 1 && rs === 1) {
            descs.push("가로병합 행" + r + " [col" + (c + 1) + "~col" + (c + cs) + "] = '" + val + "'");
        } else {
            descs.push("블록병합 [행" + r + "~행" + (r + rs - 1) + ", col" + (c + 1) + "~col" + (c + cs) + "] (" + rs + "x" + cs + ") = '" + val + "'");
        }
    }

    bottom.setReturnValue("병합 그룹 " + descs.length + "개");
    if (descs.length === 0) {
        bottom.setReturnValue("병합된 셀 없음");
    } else {
        for (let d = 0; d < descs.length; d++) bottom.setReturnValue(descs[d]);
    }

    // 제한 경계 판정 : 평가등급(col3=index2)의 우수가 왼쪽 팀(col2) 경계로 제한되어 1팀[0~1]/2팀[2]/3팀[3~4] 로 나뉘는지 확인.
    if (mode === "byrestriccol") {
        // 우수가 행0(1팀 시작)·행2(2팀 시작)·행3(3팀 시작) 에서 각각 별도 그룹으로 시작(anchor) = 팀 경계로 끊김
        let split = scwin.isAnchor(gid, 2, 0) && scwin.isAnchor(gid, 2, 2) && scwin.isAnchor(gid, 2, 3);
        bottom.setReturnValue("[제한 경계] 평가등급(우수)이 같아도 왼쪽 팀 경계로 제한되어 1팀[행0~1]/2팀[행2]/3팀[행3~4] 로 나뉘어 세로병합 : " + split);
    }
}



// 공통 : colIndex 컬럼에서 row 행이 '병합 시작(anchor)' 인지 여부 (표시되는 td 가 존재하면 anchor = 별도 그룹 시작)
scwin.isAnchor = function (gid, colIndex, row) {
    let tds = document.querySelectorAll("td[id*='" + gid + "_cell_" + row + "_" + colIndex + "']");
    for (let i = 0; i < tds.length; i++) {
        if (getComputedStyle(tds[i]).display !== 'none' && tds[i].offsetParent !== null) return true;
    }
    return false;
}
